try:
    import ortools
    print("ortools installed")
except ImportError:
    print("ortools not installed")

from z3 import *

s = Solver()
P = [Int(f'p_{i}') for i in range(12)]
for p in P:
    s.add(Or(p == 0, p == 1))

edges = []
for g in range(4):
    edges.append((P[g*3 + 0], P[g*3 + 1]))
    edges.append((P[g*3 + 1], P[g*3 + 2]))
    edges.append((P[g*3 + 0], P[g*3 + 2]))

for g in range(3):
    for i in range(3):
        edges.append((P[g*3 + i], P[(g+1)*3 + i]))

diffs = []
for u, v in edges:
    d = Int(f'd_{len(diffs)}')
    s.add(d == (u + v) % 2)
    diffs.append(d)

s.add(Sum(diffs) == 11)

if s.check() == sat:
    print("Parity SAT")
else:
    print("Parity UNSAT")
